          ]
        },
        "unit": {
          "enum": [
            "percent",
            "token",
            "credit",
            "unknown"
          ]
        },
        "status": {
          "enum": [
            "available",
            "unavailable",
            "unsupported",
            "unauthorized",
            "error",
            "stale"
          ]
        },
        "observed_at": {
