/* Pure numeric/semantic rules shared by firmware GUI and host tests.
 * All functions are dependency-free so they compile on ESP32 and the host. */

/* Percent pair must both be null or both set; when set they sum to 100 ± 0.01. */
int meter_percent_pair_ok(int used_null, double used, int rem_null, double rem);

/* Absolute token/credit windows: used+remaining == limit within 0.01. All set. */
int meter_absolute_ok(double used, double remaining, double limit);

/* Classify a window/global reset timestamp against a UTC reference.
 * resets_at may be NULL/empty -> "unknown". Returns "scheduled", "expired",
 * or "unknown" via out (NUL-terminated). strcmp-based: valid for fixed UTC. */
void meter_reset_classify(const char *resets_at, const char *reference_time,
                          char *out, unsigned out_sz);

/* Source age staleness: observed_at vs reference_time, threshold 300 s.
 * Inputs are "YYYY-MM-DDTHH:MM:SSZ" UTC. Returns 1 when age >= 300 s,
 * 0 when fresh, -1 when the timestamps are unusable (caller keeps unknown). */
int meter_source_age_stale(const char *observed_at, const char *reference_time);

#ifdef __cplusplus
}
#endif

#include "meter_validate.h"

#include <math.h>
#include <string.h>

int meter_percent_pair_ok(int used_null, double used, int rem_null, double rem) {
    if (used_null && rem_null) {
        return 1;
    }
    if (used_null != rem_null) {
        return 0;
    }
    if (used < 0 || used > 100 || rem < 0 || rem > 100) {
        return 0;
    }
    return fabs((used + rem) - 100.0) <= 0.01;
}

int meter_absolute_ok(double used, double remaining, double limit) {
    if (used < 0 || remaining < 0 || limit < 0) {
        return 0;
    }
    return fabs((used + remaining) - limit) <= 0.01;
}

void meter_reset_classify(const char *resets_at, const char *reference_time,
                          char *out, unsigned out_sz) {
    const char *unknown = "unknown";
    if (out_sz == 0) {
        return;
    }
    if (!resets_at || !*resets_at) {
        snprintf(out, out_sz, "%s", unknown);
        return;
    }
    if (!reference_time || !*reference_time) {
        snprintf(out, out_sz, "%s", unknown);
        return;
    }
    snprintf(out, out_sz, "%s", strcmp(resets_at, reference_time) >= 0 ? "scheduled" : "expired");
}

static int parse_utc(const char *s, int *y, int *mo, int *d, int *h, int *mi, int *sec) {
    if (!s || strlen(s) < 20) {
        return 0;
    }
    /* Strict "YYYY-MM-DDTHH:MM:SSZ". */
    if (s[4] != '-' || s[7] != '-' || s[10] != 'T' || s[13] != ':' || s[16] != ':' ||
        s[19] != 'Z' || s[20] != '\0') {
        return 0;
    }
    *y = (s[0] - '0') * 1000 + (s[1] - '0') * 100 + (s[2] - '0') * 10 + (s[3] - '0');
    *mo = (s[5] - '0') * 10 + (s[6] - '0');
    *d = (s[8] - '0') * 10 + (s[9] - '0');
    *h = (s[11] - '0') * 10 + (s[12] - '0');
    *mi = (s[14] - '0') * 10 + (s[15] - '0');
    *sec = (s[17] - '0') * 10 + (s[18] - '0');
    if (*mo < 1 || *mo > 12 || *d < 1 || *d > 31 || *h > 23 || *mi > 59 || *sec > 60) {
        return 0;
    }
    return 1;
}

static long long days_from_civil(int y, int m, int d) {
    y -= m <= 2;
    const long long era = (y >= 0 ? y : y - 399) / 400;
    const unsigned yoe = (unsigned)(y - era * 400);
    const unsigned doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + (unsigned)(d - 1);
    const unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + (long long)doe - 719468;
}

int meter_source_age_stale(const char *observed_at, const char *reference_time) {
    int y1, mo1, d1, h1, mi1, s1, y2, mo2, d2, h2, mi2, s2;
    if (!parse_utc(observed_at, &y1, &mo1, &d1, &h1, &mi1, &s1)) {
        return -1;
    }
    if (!parse_utc(reference_time, &y2, &mo2, &d2, &h2, &mi2, &s2)) {
        return -1;
    }
    long long t1 = days_from_civil(y1, mo1, d1) * 86400LL + h1 * 3600LL + mi1 * 60LL + s1;
    long long t2 = days_from_civil(y2, mo2, d2) * 86400LL + h2 * 3600LL + mi2 * 60LL + s2;
    long long age = t2 - t1;
    if (age < 0) {
        return -1; /* future observed_at: caller reports FUTURE_TIMESTAMP */
    }
    return age >= 300 ? 1 : 0;
}

#pragma once
#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

#define GUI_LINES_MAX 12
#define GUI_LINE_CHARS 64
#define GUI_SCREENS 3 /* 0 dashboard, 1 global reset, 2 status/error */

/* Logical landscape canvas: 820x320. Text uses a 8x16 cell font so the
 * safe grid is 820/8=102 cols x 320/16=20 rows; lines are capped at 64
 * chars so nothing clips on the real panel. */
typedef struct {
    char lines[GUI_LINES_MAX][GUI_LINE_CHARS + 1];
    int count;
} gui_screen_text_t;

/* Render one dashboard line for a provider/window. All strings are verbatim
 * from the frame payload (never invented). Missing values render as "n/a". */
void gui_dashboard_line(const char *provider, const char *window,
                        const char *percent_used, const char *unit,
                        const char *resets_at, const char *observed_at,
                        char *out, size_t out_sz);

/* Global reset screen. Shows codex-resets.com latest reset + age text
 * supplied by the caller (firmware passes receive-age; "unknown" when the
 * wall-clock base is not established), or the default screen. */
void gui_global_text(const char *source, const char *latest_reset_at,
                     const char *captured_at, const char *age_text, int has_reset,
                     gui_screen_text_t *out);

/* Status screen: link / parse-error / stale / last-good / retry state. */
void gui_status_text(int link_ok, const char *last_error, int stale,
                     const char *last_good_at, const char *retry,
                     gui_screen_text_t *out);

/* Returns 1 when every line fits the 64-char landscape budget. */
int gui_layout_fits(const gui_screen_text_t *screen);

const char *gui_screen_name(int screen);

#ifdef __cplusplus
}
#endif

#include "gui_format.h"

#include <stdio.h>
#include <string.h>

const char *gui_screen_name(int screen) {
    switch (screen) {
        case 0: return "DASHBOARD";
        case 1: return "GLOBAL RESET";
        case 2: return "STATUS";
        default: return "?";
    }
}

static const char *or_na(const char *s) {
    return (s && *s) ? s : "n/a";
}

void gui_dashboard_line(const char *provider, const char *window,
                        const char *percent_used, const char *unit,
                        const char *resets_at, const char *observed_at,
                        char *out, size_t out_sz) {
    char pct[32];
    if (percent_used && *percent_used) {
        snprintf(pct, sizeof pct, "%s%%", percent_used);
    } else {
        snprintf(pct, sizeof pct, "n/a");
    }
    snprintf(out, out_sz, "%s/%s %s %s rst:%s obs:%s", or_na(provider),
             or_na(window), pct, or_na(unit), or_na(resets_at), or_na(observed_at));
    out[out_sz - 1] = '\0';
}

void gui_global_text(const char *source, const char *latest_reset_at,
                     const char *captured_at, const char *age_text, int has_reset,
                     gui_screen_text_t *out) {
    memset(out, 0, sizeof *out);
    if (!has_reset) {
        snprintf(out->lines[0], sizeof out->lines[0], "GLOBAL RESET: default (no history)");
        snprintf(out->lines[1], sizeof out->lines[1], "src:%s", or_na(source));
        snprintf(out->lines[2], sizeof out->lines[2], "obs:%s", or_na(captured_at));
        out->count = 3;
        return;
    }
    snprintf(out->lines[0], sizeof out->lines[0], "GLOBAL RESET src:%s", or_na(source));
    snprintf(out->lines[1], sizeof out->lines[1], "latest:%s", or_na(latest_reset_at));
    snprintf(out->lines[2], sizeof out->lines[2], "age:%s obs:%s", or_na(age_text), or_na(captured_at));
    out->count = 3;
}

void gui_status_text(int link_ok, const char *last_error, int stale,
                     const char *last_good_at, const char *retry,
                     gui_screen_text_t *out) {
    memset(out, 0, sizeof *out);
    snprintf(out->lines[0], sizeof out->lines[0], "LINK:%s STALE:%s", link_ok ? "USB-OK" : "USB-LOST",
             stale ? "YES" : "NO");
    snprintf(out->lines[1], sizeof out->lines[1], "ERR:%s", or_na(last_error));
    snprintf(out->lines[2], sizeof out->lines[2], "LAST-GOOD:%s", or_na(last_good_at));
    snprintf(out->lines[3], sizeof out->lines[3], "RETRY:%s", or_na(retry));
    out->count = 4;
}

int gui_layout_fits(const gui_screen_text_t *screen) {
    if (!screen || screen->count < 0 || screen->count > GUI_LINES_MAX) {
        return 0;
    }
    for (int i = 0; i < screen->count; i++) {
        if (strlen(screen->lines[i]) > GUI_LINE_CHARS) {
            return 0;
        }
    }
    return 1;
}

#pragma once
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Selected onboard feature: link/idle-aware backlight auto-dim.
 * Separate from the core meter path; core rendering never depends on it.
 * Backlight is active-low (GPIO6): duty = 255 - brightness. */

#define AUTODIM_BRIGHT_NORMAL 200u
#define AUTODIM_BRIGHT_DIM 60u
#define AUTODIM_IDLE_SECONDS 30u

typedef struct {
    uint64_t last_activity_s; /* last accepted frame or BOOT press */
    int link_ok;
} autodim_state_t;

void autodim_init(autodim_state_t *s, uint64_t now_s);

/* Returns the 8-bit LEDC duty for the current conditions. Pure logic. */
uint8_t autodim_duty(const autodim_state_t *s, uint64_t now_s);

/* 1 when the panel is in dimmed standby, else 0. */
int autodim_is_dimmed(const autodim_state_t *s, uint64_t now_s);

#ifdef __cplusplus
}
#endif

#include "feature_auto_dim.h"

void autodim_init(autodim_state_t *s, uint64_t now_s) {
    s->last_activity_s = now_s;
    s->link_ok = 1;
}

static int idle(const autodim_state_t *s, uint64_t now_s) {
    uint64_t age = now_s >= s->last_activity_s ? now_s - s->last_activity_s : 0;
    return age >= AUTODIM_IDLE_SECONDS;
}

int autodim_is_dimmed(const autodim_state_t *s, uint64_t now_s) {
    if (!s->link_ok) {
        return 1;
    }
    return idle(s, now_s);
}

uint8_t autodim_duty(const autodim_state_t *s, uint64_t now_s) {
    uint8_t bright = autodim_is_dimmed(s, now_s) ? AUTODIM_BRIGHT_DIM : AUTODIM_BRIGHT_NORMAL;
    return (uint8_t)(255u - bright);
}

