input.oldString:
/* Fractional sequence rejected. */
{
    char frac[8192];
    size_t flen = build_frame(frac, sizeof frac, 7, "2026-09-10T00:04:59Z", "", "");
    char *q = strstr(frac, "\"sequence\":7");
    memmove(q + 13, q + 12, flen - (size_t)(q + 12 - frac));
    memcpy(q + 12, ".5", 2);
    /* Recompute CRC over the unsigned part is skipped: absence of integer
     * sequence must already fail with SEQUENCE_INVALID before CRC. */
    (void)flen;
    meter_frame_info_t fi;
    int rc = meter_frame_check((const unsigned char *)frac, flen + 1, &fi);
    CHECK(rc == METER_FRAME_SEQUENCE_INVALID || rc == METER_FRAME_CRC_MISMATCH);
}

input.newString:
/* Fractional sequence rejected (valid CRC, integer check first). */
{
    const char *unsigned_fmt =
        "{\"payload\":{\"global_resets\":[],\"usage\":[]},"
        "\"protocol\":\"cdm/1\",\"sent_at\":\"2026-09-10T00:04:59Z\","
        "\"sequence\":7.5}";
    char hex2[9];
    meter_crc32_hex((const unsigned char *)unsigned_fmt, strlen(unsigned_fmt), hex2);
    char frac[8192];
    int m = snprintf(frac, sizeof frac,
                     "{\"integrity\":{\"algorithm\":\"crc32\",\"value\":\"%s\"},"
                     "%s}\n",
                     hex2, unsigned_fmt + 1);
    /* unsigned_fmt+1 strips the leading '{'; re-add via the prefix above. */
    assert(m > 0 && (size_t)m < sizeof frac);
    meter_frame_info_t fi;
    int rc = meter_frame_check((const unsigned char *)frac, (size_t)m, &fi);
    CHECK(rc == METER_FRAME_SEQUENCE_INVALID);
}

